options.getOption:
const nodes = new Map();
const links = new Map();
let observed = false;
for (const frame of context.panel.data.series) {
  for (const field of frame.fields.filter((f) => f.type === "number")) {
    const value = field.values[field.values.length - 1];
    if (!Number.isFinite(value) || value < 0) continue;
    observed = true;
    if (value === 0) continue;
    const labels = field.labels || {};
    const billing = ["free", "local", "paid", "subscription"].filter(
      (name) => labels["tag_telemetry_billing_class_" + name] === "true"
    );
    const path = [
      labels.team || "unattributed caller",
      billing.length ? billing.join(" + ") : "unclassified",
      labels.api_provider || "unknown provider",
      labels.model || "unknown model",
    ].map((displayName, depth) => {
      const name = JSON.stringify([depth, displayName]);
      nodes.set(name, { name, displayName, depth });
      return name;
    });
    for (let i = 0; i < path.length - 1; i++) {
      const source = path[i], target = path[i + 1];
      const key = JSON.stringify([source, target]);
      const link = links.get(key) || { source, target, value: 0 };
      link.value += value;
      links.set(key, link);
    }
  }
}
return {
  backgroundColor: "#0b1220",
  color: ["#60a5fa", "#34d399", "#fbbf24", "#a78bfa", "#fb7185"],
  title: {
    text: links.size ? "" : observed ? "No output tokens in selected range" : "No output-token telemetry in selected range",
    left: "center", top: "middle", textStyle: { color: "#cbd5e1", fontSize: 18 },
  },
  tooltip: {
    trigger: "item", renderMode: "richText",
    formatter: (p) => p.dataType === "edge"
      ? nodes.get(p.data.source).displayName + " → " + nodes.get(p.data.target).displayName + ": " + p.data.value.toFixed(2) + " tok/s"
      : p.data.displayName,
  },
  series: [{
    type: "sankey", left: "3%", right: "25%", top: 30, bottom: 30,
    nodeWidth: 18, nodeGap: 14, nodeAlign: "justify",
    data: [...nodes.values()], links: [...links.values()],
    label: { color: "#e8edf5", fontSize: 14, formatter: (p) => p.data.displayName },
    lineStyle: { color: "gradient", opacity: 0.45, curveness: 0.5 },
    emphasis: { focus: "adjacency" },
  }],
};
